private boolean coreVerifyPin(byte[] buffer, short offset, byte len) {

    byte checksum = PinHelper.foldChecksum(buffer, offset, len);

    for (short i = 0; i < len; i++) {
        if (buffer[(short) (offset + i)] != referencePin[i]) {
            triesLeft--;
            return false;
        }
    }

    triesLeft = 3;
    return true;
}

