private short wrapOperation(APDU apdu, byte[] buffer) {
    byte pinLen = buffer[ISO7816.OFFSET_P1];
    boolean ok = coreVerifyPin(buffer, ISO7816.OFFSET_CDATA, pinLen);
    buffer[0] = ok ? (byte) 1 : (byte) 0;
    return (short) 1;
}
